import json
from typing import Optional
from fastapi import APIRouter, HTTPException

from app.services.decision_engine import decision_engine
from app.database import get_db_connection

router = APIRouter(prefix="/api/prompts", tags=["prompts"])

@router.get("")
async def list_active_prompts():
    """Retrieve active prompts, nudges, and reminders generated by graph reasoning."""
    return decision_engine.get_active_prompts()

@router.post("/sweep")
async def trigger_prompt_sweep():
    """Manually trigger a graph sweep to detect anomalies, stalemates, or approaching deadlines."""
    new_prompts = decision_engine.run_proactive_prompt_sweep()
    return {"created_count": len(new_prompts), "new_prompts": new_prompts}

@router.post("/{prompt_id}/resolve")
async def resolve_prompt(prompt_id: str, status: str = "resolved"):
    success = decision_engine.resolve_prompt(prompt_id, new_status=status)
    return {"success": success}

@router.get("/decision-logs")
async def get_decision_logs(limit: int = 25):
    """View explainable decision model logs showing why items were prioritized or scheduled."""
    conn = get_db_connection()
    rows = conn.execute("SELECT * FROM decision_logs ORDER BY created_at DESC LIMIT ?", (limit,)).fetchall()
    conn.close()
    results = []
    for r in rows:
        d = dict(r)
        d["input_context"] = json.loads(d.get("input_context_json") or "{}")
        d["output_decision"] = json.loads(d.get("output_decision_json") or "{}")
        results.append(d)
    return results
